<?php declare(strict_types=1);
use Kulturhus\Verein\{SettingsSchema};use Kulturhus\Verein\Settings\TextInput;
$tt=static fn(string $text):string=>\Kulturhus\Native\Language\TextSettingsMessages::text($text,$textsettingsMessages);
$tv=static fn(mixed $value):string=>is_bool($value)?($value?'1':'0'):(is_scalar($value)?(string)$value:'');
$turl=static fn(array $q=[],?string $scope=null):string=>url(['view'=>'settings','tab'=>'texts','group'=>substr($scope??$textsettingsScope,6)]+$q);
$tvalues=static function(array $data,string $scope)use($tt,$tv):void{foreach(SettingsSchema::templateLabels($scope)as$key=>$label){?><h4><?=e($tt($label))?></h4><dl class="general-settings-description"><?php foreach(TextInput::FIELDS as$field=>$name): ?><dt><?=e($tt($name))?></dt><dd><?php if($field==='attach_pdf'): ?><?=e(is_bool($data[$key][$field]??null)?$tt($data[$key][$field]?'Ja':'Nein'):$tv($data[$key][$field]??''))?><?php else: ?><pre class="general-settings-values"><?="\n".e($tv($data[$key][$field]??''))?></pre><?php endif ?></dd><?php endforeach ?></dl><?php }};
?>
