<?php if(!$textsettingsDraft||$textsettingsDraft['accepted']!==null): ?><section class="card"><nav class="general-settings-actions" aria-label="<?=e($tt('Textbausteingruppen'))?>"><?php foreach(TextInput::GROUPS as$scope=>$name): ?><a class="btn btn-outline theme-secondary" href="<?=e($turl(['textsettings_new'=>'1'],$scope))?>"><?=e($tt($name))?></a><?php endforeach ?></nav><a class="btn btn-solid theme-primary" href="<?=e($turl(['textsettings_new'=>'1']))?>"><?=e($tt('Neuen eigenen Textbausteinentwurf öffnen'))?></a></section>
