<?php if($editable): ?><nav class="general-settings-actions" aria-label="<?=e($tt('Entwurf erhalten und Gruppe wechseln'))?>"><?php foreach(TextInput::GROUPS as$scope=>$name):if($scope===$textsettingsScope)continue; ?><button class="btn btn-outline theme-secondary" name="textsettings_intent" value="switch:<?=e($scope)?>"><?=e($tt($name))?></button><?php endforeach ?></nav><?php endif ?>
