<details><summary><?=e($tt('Verfügbare Variablen'))?></summary><dl class="general-settings-description"><?php foreach(SettingsSchema::VARIABLES as$key=>$label): ?><dt><code>{{<?=e($key)?>}}</code></dt><dd><?=e($tt($label))?></dd><?php endforeach ?></dl></details>
<?php foreach($labels as$template=>$name): ?><fieldset class="general-settings-row" data-textsettings-template="<?=e($template)?>"><legend><?=e($tt($name))?></legend><p><?=e($tt($template==='invoice'?'Betreff und Benachrichtigung gehören zur E-Mail-Vorschau. Einleitung und Schlusstext gehören zum Rechnungs-PDF.':'Diese Briefvorlage verwendet Betreff und Benachrichtigungstext.'))?></p>
<?php foreach(TextInput::FIELDS as$field=>$label):$raw=$tv($input['data'][$template][$field]);$fieldName='data['.$template.']['.$field.']';if($field==='intro'&&$template!=='invoice'): ?><details><summary><?=e($tt('Weitere erhaltene Textangaben'))?></summary><p><?=e($tt('Einleitung und Schlusstext bleiben hier erhalten. Für diese Briefvorlage wird der Benachrichtigungstext verwendet.'))?></p><?php endif ?>
<?php if($field==='attach_pdf'):$choices=['0'=>'Nein','1'=>'Ja']; ?><label class="general-settings-field"><?=e($tt($label))?><select class="form-control" name="<?=e($fieldName)?>" <?=$editable?'':'disabled'?>><?php if(!array_key_exists($raw,$choices)): ?><option selected value="<?=e($raw)?>"><?=e($raw)?></option><?php endif;foreach($choices as$value=>$choice): ?><option value="<?=e($value)?>" <?=$raw===(string)$value?'selected':''?>><?=e($tt($choice))?></option><?php endforeach ?></select></label>
