<?php else: ?><div class="rich-field"><label class="general-settings-field"><?=e($tt($label))?><textarea class="form-control" name="<?=e($fieldName)?>" rows="<?=$field==='message'?'9':'4'?>" data-rich-input <?=$editable?'':'readonly'?>><?="\n".e($raw)?></textarea></label><?php if($editable): ?><div class="rich-toolbar general-settings-actions" hidden data-textsettings-toolbar role="group" aria-label="<?=e($tt('Text formatieren'))?>"><button type="button" class="btn btn-outline theme-secondary" data-format="**" aria-label="<?=e($tt('Fett'))?>"><strong>B</strong></button><button type="button" class="btn btn-outline theme-secondary" data-format="*" aria-label="<?=e($tt('Kursiv'))?>"><em>I</em></button><button type="button" class="btn btn-outline theme-secondary" data-format="__" aria-label="<?=e($tt('Unterstrichen'))?>"><u>U</u></button><select class="form-control" data-variable aria-label="<?=e($tt('Variable auswählen'))?>"><option value=""><?=e($tt('Variable wählen'))?></option><?php foreach(SettingsSchema::VARIABLES as$key=>$name): ?><option value="<?=e($key)?>"><?=e($tt($name))?></option><?php endforeach ?></select><button type="button" class="btn btn-outline theme-secondary" data-insert-variable><?=e($tt('Einfügen'))?></button></div><?php endif ?><details><summary><?=e($tt('Formatierte Eingabe ansehen'))?></summary><div class="rich-preview" data-rich-preview><?=SettingsSchema::html($raw)?></div></details></div><?php endif ?>
<?php if($field==='closing'&&$template!=='invoice'): ?></details><?php endif;endforeach;if($editable): ?><button class="btn btn-outline theme-secondary" name="textsettings_intent" value="reset:<?=e($template)?>"><?=e($tt('Nur diese Vorlage auf Standard zurücksetzen'))?></button><?php endif ?></fieldset><?php endforeach ?>
