k"><input class="check" type="checkbox" name="textsettings_approved" value="1"><span><?=e($tt('Die vollständige Textbausteingruppe und alle ihre Vorschauen sind geprüft.'))?></span></label><button class="btn btn-solid theme-primary" name="textsettings_intent" value="accept"><?=e($tt('Geprüfte Textbausteingruppe bestätigen'))?></button></form></section><?php endif ?></section><?php endif ?>
